{
  "title": "Who Should Manage DoD ELINT?",
  "setting": "United States, early 1958, National Security Council and Department of Defense.",
  "decider": "The National Security Council",
  "agent_recast": false,
  "recast_note": "",
  "agent": "The National Security Council",
  "agent_role": "decide",
  "situation": "By early 1958, the military departments maintained their own interests in DoD ELINT, while management by NSA was under consideration. ANEEG and its successor, NTPC, provided a centralized point for ELINT analysis, but ANEEG's coordinating powers were informal. DoD ELINT was assessed as needing more coordination and cohesive signal analysis and processing. Presidential-level committees had recommended bringing ELINT under NSA, and the President supported that direction. The National Security Council faced a choice about whether to centralize management under NSA, retain management among the military departments, or assign NSA a narrower coordinating role.",
  "question": "What should the National Security Council do about the management of DoD ELINT?",
  "facts": [
    {
      "id": "F1",
      "kind": "situation",
      "status": "confirmed",
      "fact": "When NSA was formed in 1952, including ELINT in its charter was considered alongside COMINT.",
      "spans": [
        "src:d509d15635b8#p6.2"
      ]
    },
    {
      "id": "F2",
      "kind": "situation",
      "status": "confirmed",
      "fact": "The military departments wanted to manage their own ELINT interests and did not want NSA to manage ELINT.",
      "spans": [
        "src:d509d15635b8#p6.2"
      ]
    },
    {
      "id": "F3",
      "kind": "capability",
      "status": "assessed",
      "fact": "DoD ELINT needed coordination and management, particularly a cohesive signal analysis and processing effort.",
      "spans": [
        "src:d509d15635b8#p6.3"
      ]
    },
    {
      "id": "F4",
      "kind": "situation",
      "status": "confirmed",
      "fact": "In 1952, ANEEG was established as a centralized ELINT analysis point and a focal point for difficult analytic problems, with informal coordinating powers.",
      "spans": [
        "src:d509d15635b8#p7.4"
      ]
    },
    {
      "id": "F5",
      "kind": "situation",
      "status": "confirmed",
      "fact": "In 1955, ANEEG was redesignated as NTPC under the USAF Air Staff as ELINT processing problems grew.",
      "spans": [
        "src:d509d15635b8#p7.5"
      ]
    },
    {
      "id": "F6",
      "kind": "authority",
      "status": "confirmed",
      "fact": "Presidential-level committees in 1954 and 1957 recommended bringing ELINT under NSA's purview.",
      "spans": [
        "src:d509d15635b8#p8.3"
      ]
    },
    {
      "id": "F7",
      "kind": "authority",
      "status": "confirmed",
      "fact": "The President strongly backed efforts to have NSA manage U.S. ELINT.",
      "spans": [
        "src:d509d15635b8#p8.3"
      ]
    }
  ],
  "options": {
    "O1": {
      "do": "The National Security Council would centralize DoD ELINT management under NSA.",
      "move": "act",
      "disposition": "centralize",
      "irreversible": false
    },
    "O2": {
      "do": "The National Security Council would decentralize DoD ELINT management among the military departments.",
      "move": "act",
      "disposition": "decentralize",
      "irreversible": false
    },
    "O3": {
      "do": "The National Security Council would assign NSA a coordinating role while preserving departmental ELINT management.",
      "move": "partial",
      "to": "NSA",
      "disposition": "coordinate",
      "irreversible": false
    }
  },
  "opposite_pair": [
    "O1",
    "O2"
  ],
  "real_option": "O1",
  "authored_options": [
    "O2",
    "O3"
  ],
  "no_opposite_reason": ""
}

